"""Low-level tools for creating servers."""

import typing

from jsilib import _utils
from jsilib.base import IClosable

from ._endpoint import load_from_url
from ._tcp import TCPServer
from ._ws import WSServer
from .acceptor import ForwardingAcceptor
from .interface import IAcceptor, IReactor, IStream

__all__ = export = _utils.ExportList()


@export
class Server(IAcceptor):
    """Factory class for the server-side connections.

    :param reactor:
        Reactor to be used by this server and all connections accepted by this
        server.
    """
    _handlers_supported = {
        'tcp': TCPServer,
        'tcp+ssl': TCPServer,
        'ws': WSServer,
        'wss': WSServer,
    }

    def __init__(self, reactor: IReactor):
        self._reactor = reactor
        self._closed = False
        self._forwarder = ForwardingAcceptor()
        self._handlers_created: typing.List[IClosable] = []

    async def bind(self, url: str):
        """Bind this server to the given *url* and start listening to the
        incoming connection at that *url*.

        It is possible to bind the server to several URLs at once, making it
        handling several protocols at once.

        :param url:
            URL address to bind the server to.

            For example, to bind to the TCP at host **localhost** and port
            **8888**, you would write:

                tcp://localhost:8888

            Currently supported protocols (i.e. URL schemes) are:

                * tcp - for TCP connections
                * tcp+ssl - for secure TCP connections
                * ws - for WebSocket connections
                * wss - for secure WebSocket connections
        """
        endpoint = load_from_url(url)
        handler_factory = self._handlers_supported.get(endpoint.scheme)
        if handler_factory is None:
            raise ValueError(f'unsupported scheme: {endpoint.scheme}')
        handler = handler_factory(self._reactor, self._forwarder)
        self._handlers_created.append(handler)
        await handler.bind(endpoint)

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            for handler in self._handlers_created:
                await handler.close()
            await self._forwarder.close()

    async def accept(self) -> IStream:
        return await self._forwarder.accept()
